'use strict';
const $=s=>document.querySelector(s);
const escapeHTML=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=u=>{try{let v=new URL(u);return ['https:','http:'].includes(v.protocol)?escapeHTML(u):'#';}catch{return '#';}};
const link=(url,label,cls='source-ref')=>`<a class="${cls}" href="${safeURL(url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(label)} ↗</a>`;
const cats=['全部',...new Set(BUILDERS.map(p=>p.category))];
let category='全部',selected='overview',format='diagram',step=0,timer=null,methodFormat=1;
const methodNames=['清楚的文字','关系图解','交互网页','讲解视频'];
const methodNotes=[
['把一句话拆成可检查的意思。','Karpathy 建议用 ASD-STE100，或接近它的写法，让模型写得更清楚。这里借用短句、明确动作和稳定术语的原则；中文示例不声称符合该英文规范。'],
['把关系画出来，减少脑内拼图。','图解适合结构、步骤和关系。先看全貌，再选择一个节点读细节。图里应说明连线的含义，避免把并列观点误读为因果。'],
['让读者操作，看到条件如何改变结果。','HTML 网页可以把解释变成可操作的软件。它可以服务一次具体的理解任务，不一定需要长期维护成一个产品。'],
['用时间顺序、画面和声音共同解释。','Karpathy 最看好按主题定制的讲解视频。先设计每一幕要解释什么，再生成画面与旁白。本页提供脚本示例和分步网页讲解，尚未生成视频文件。']
];
function stopPlayer(){if(timer)clearInterval(timer);timer=null;}
function renderCategories(){$('#categories').innerHTML=cats.map(c=>`<button type="button" class="${c===category?'active':''}" aria-pressed="${c===category}" data-cat="${escapeHTML(c)}">${escapeHTML(c)}</button>`).join('');}
function renderIndex(){const q=$('#search').value.trim().toLowerCase();const list=BUILDERS.filter(p=>(category==='全部'||p.category===category)&&JSON.stringify([p,LEARNING[p.id],X_INSIGHTS.profiles.find(x=>x.id===p.id)]).toLowerCase().includes(q));$('#count').textContent=`${list.length} / ${BUILDERS.length}`;$('#empty').hidden=!!list.length;$('#people').innerHTML=list.map(p=>`<a class="person-button ${p.id===selected?'active':''}" href="#${p.id}" ${p.id===selected?'aria-current="page"':''}><span class="num">${String(BUILDERS.indexOf(p)+1).padStart(2,'0')}</span><span><strong>${escapeHTML(p.name)}</strong><small>${escapeHTML(p.short)}</small></span></a>`).join('');$('.overview-link').setAttribute('aria-current',selected==='overview'?'page':'false');}
function renderMethod(){const focused=document.activeElement?.dataset?.method;const [title,note]=methodNotes[methodFormat];let demo='';
if(methodFormat===0)demo='<div class="plain-example"><p><b>Agent 写完代码。</b>这只表示代码已生成。</p><p><b>运行检查。</b>确认代码是否满足任务条件。</p><p><b>人核对结果。</b>决定是否交付。</p></div>';
if(methodFormat===1)demo='<div class="example-flow"><span>Agent 生成代码</span><i>→</i><span>工具检查结果</span><i>→</i><span>人判断是否交付</span></div><p class="micro">箭头表示示例中的执行顺序。检查失败时，应返回修改。</p>';
if(methodFormat===2)demo='<div class="check-demo"><p>试着改变验收条件，观察结论。</p><label><input type="checkbox" id="test-check">自动检查通过</label><label><input type="checkbox" id="human-check">人已核对任务结果</label><output id="demo-result" aria-live="polite">已生成代码，尚未完成验收。</output><p class="micro">这是教学示例，没有运行真实代码或调用模型。</p></div>';
if(methodFormat===3)demo='<ol class="storyboard"><li><b>第一幕：生成</b><span>画面显示代码出现。旁白：“写完代码，还不等于完成任务。”</span></li><li><b>第二幕：检查</b><span>画面显示测试与反馈。旁白：“检查失败，就返回修改。”</span></li><li><b>第三幕：判断</b><span>画面显示人核对结果。旁白：“工具提供证据，人决定是否交付。”</span></li></ol><p class="micro">视频脚本示例，未生成视频或音频。</p>';
$('#method-demo').innerHTML=`<div class="demo-heading"><span class="eyebrow">${String(methodFormat+1).padStart(2,'0')} / ${methodNames[methodFormat]}</span><h3>${title}</h3></div><p>${note}</p><div class="demo-surface"><span class="micro">同一个例子：怎样理解 Agent 完成任务？</span>${demo}</div>`;
$('#method-formats').innerHTML=methodNames.map((n,i)=>`<button data-method="${i}" aria-pressed="${i===methodFormat}"><span>0${i+1}</span>${n}</button>`).join('');if(focused!==undefined)document.querySelector(`[data-method="${focused}"]`)?.focus({preventScroll:true});}
function renderOverview(){const count=BUILDERS.reduce((n,p)=>n+p.works.length,0);$('#profile').innerHTML=`<div class="profile-topline"><span class="eyebrow">A MAP FOR UNDERSTANDING</span><span>30 份档案 · ${count} 条原文</span></div><div class="overview-hero"><p class="kicker">从收集信息，到理解观点</p><h1>让 AI 做更多。<br>让自己看得更明白。</h1><p class="hero-copy">模型承担执行，人负责理解、监督与判断。借用 Karpathy 的方法，把建造者的观点变成可以阅读、点击和逐步理解的解释。</p><a class="text-action" href="#karpathy">从 Karpathy 开始 ↗</a></div><section class="teaching-section"><div class="section-heading"><span class="eyebrow">01 / THE METHOD</span><h2>选择适合问题的表达方式</h2></div><p class="section-intro">短句讲清意思，图解展示关系，网页让人试一试，视频组织时间与旁白。无需每次都做最复杂的形式。</p><div id="method-formats" class="method-formats" aria-label="表达方式"></div><div id="method-demo" class="method-demo"></div><p class="source-line">方法依据：Karpathy 关于理解模型输出的原帖。${link('https://x.com/karpathy/status/2105819303471976479','查看原帖')}。上面的例子由本档案编写。</p></section><section class="teaching-section"><div class="section-heading"><span class="eyebrow">02 / READING PATHS</span><h2>带着一个问题去读</h2></div><p class="section-intro">每条路线按理解顺序组织，不是作者之间的合作关系或观点排名。</p><div class="routes">${ROUTES.map((r,i)=>`<article class="route"><div class="route-heading"><span class="route-number">0${i+1}</span><div><p class="micro">${r.question}</p><h3>${r.title}</h3></div></div><ol>${r.ids.map((id,n)=>{const p=BUILDERS.find(p=>p.id===id);return `<li><a href="#${id}"><span class="route-step">${n+1}</span><span><strong>${r.labels[n]}</strong><small>${escapeHTML(p.name)}</small></span><span aria-hidden="true">↗</span></a></li>`;}).join('')}</ol></article>`).join('')}</div></section><section class="learning-rule"><span class="eyebrow">READ → EXPLAIN → CHECK</span><h2>读完，试着解释给别人。</h2><p>用一句话说出主张。用图说明关系。找一个实际任务检验它。最后回到原文，确认作者说了什么，以及哪些部分只是自己的推断。</p><p class="micro">本页的路线与练习是编辑设计。作者观点和原始证据在每份档案中保留。</p></section>`;renderMethod();document.title='Builder Atlas · AI 建造者理解地图';}
function archiveHTML(p){return `<div class="section-heading"><span class="eyebrow">01 / IDEAS</span><h3>${p.official?'官方内容主线':'主要观点'}</h3></div><div class="ideas">${p.ideas.map((i,n)=>`<article class="idea"><span class="idea-number">${String(n+1).padStart(2,'0')}</span><div><h4>${escapeHTML(i.title)}</h4><p>${escapeHTML(i.text)}</p><a class="source-ref" href="${safeURL(p.works[i.source||0].url)}" target="_blank" rel="noopener noreferrer">依据：${escapeHTML(p.works[i.source||0].title)}</a></div></article>`).join('')}</div><div class="section-heading"><span class="eyebrow">02 / READING</span><h3>代表内容</h3></div><div class="works">${p.works.map((w,n)=>`<article class="work"><div class="work-meta"><span class="work-type">${escapeHTML(w.type)}</span><span>${escapeHTML(w.date)}</span><span>${escapeHTML(w.author)}</span></div><h4><a href="${safeURL(w.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(w.title)}</a></h4><p>${escapeHTML(w.summary)}</p><p class="reading-reason"><b>为什么值得读</b>　${escapeHTML(w.why)}</p>${w.access?`<p class="access">${escapeHTML(w.access)}</p>`:''}${w.evidence?`<a class="source-ref" href="${safeURL(w.evidence)}" target="_blank" rel="noopener noreferrer">已读取的逐字稿／镜像依据</a>`:''}<a class="work-link" href="${safeURL(w.url)}" target="_blank" rel="noopener noreferrer">${w.type.includes('访谈')||w.type.includes('演讲')?'观看／收听原内容':'阅读原内容'}</a></article>`).join('')}</div><div class="reading-note"><b>阅读提示 · 编辑判断</b>${escapeHTML(p.note)}</div>`;}
function renderLesson(){const active=document.activeElement;const key=['format','step','control'].find(k=>active?.dataset?.[k]!==undefined);const value=key?active.dataset[key]:null;const p=BUILDERS.find(p=>p.id===selected);const i=p.ideas[step];const source=p.works[i.source||0];let content='';
if(format==='text')content=`<div class="plain-lesson">${p.ideas.map((idea,n)=>`<article><span class="micro">0${n+1}</span><h3>${escapeHTML(idea.title)}</h3><p>${escapeHTML(LEARNING_IDEAS[p.id][n])}</p>${link(p.works[idea.source||0].url,'查看这条观点的依据')}</article>`).join('')}</div>`;
else if(format==='diagram')content=`<div class="idea-map"><div class="map-root"><span class="micro">核心主张</span><p>${escapeHTML(p.thesis)}</p></div><div class="map-branches" style="--nodes:${p.ideas.length}">${p.ideas.map((idea,n)=>`<button data-step="${n}" aria-pressed="${n===step}"><span class="micro">观点 0${n+1}</span><strong>${escapeHTML(idea.title)}</strong></button>`).join('')}</div><p class="micro map-caption">连线表示主张与相关观点。点击节点查看解释和证据。</p></div><article class="step-detail"><span class="eyebrow">0${step+1} / ${String(p.ideas.length).padStart(2,'0')}</span><h3>${escapeHTML(i.title)}</h3><p>${escapeHTML(LEARNING_IDEAS[p.id][step])}</p>${link(source.url,'依据：'+source.title)}</article>`;
else content=`<div class="step-progress" aria-label="讲解进度">${p.ideas.map((_,n)=>`<button data-step="${n}" class="${n===step?'active':''}" aria-label="第 ${n+1} 步" aria-pressed="${n===step}">${n+1}</button>`).join('')}</div><article class="step-detail presentation"><span class="eyebrow">STEP 0${step+1} / ${String(p.ideas.length).padStart(2,'0')}</span><h3>${escapeHTML(i.title)}</h3><p>${escapeHTML(LEARNING_IDEAS[p.id][step])}</p>${link(source.url,'依据：'+source.title)}</article><div class="player-controls"><button data-control="prev" ${step===0?'disabled':''}>← 上一步</button><button data-control="play" aria-pressed="${!!timer}">${timer?'暂停讲解':'自动讲解'}</button><button data-control="next" ${step===p.ideas.length-1?'disabled':''}>下一步 →</button></div><p class="micro">网页分步讲解，每 8 秒前进一步，可随时暂停。这不是视频文件。</p>`;
$('#lesson').innerHTML=content;$('#lesson-formats').innerHTML=[['text','短句阅读'],['diagram','观点地图'],['steps','分步讲解']].map(([id,n])=>`<button data-format="${id}" aria-pressed="${format===id}">${n}</button>`).join('');if(key)document.querySelector(`[data-${key}="${value}"]`)?.focus({preventScroll:true});}
function recentXHTML(p){
const x=X_INSIGHTS.profiles.find(x=>x.id===p.id);
const heading='<div class="section-heading"><span class="eyebrow">03 / RECENT X INSIGHTS</span><h2>近期 X 观点</h2></div>';
if(!x?.insights?.length)return `<section class="recent-x" aria-label="近期 X 观点">${heading}<div class="x-empty"><strong>本轮尚未取得有效样本</strong><p>本批采集遇到 X 限流，已停止。此账号暂无近期推文总结；不代表作者没有发表观点。</p><small>采集批次：${escapeHTML(X_INSIGHTS.collectedDate)} · 已完成 9 / 30 个账号</small></div></section>`;
return `<section class="recent-x" aria-label="近期 X 观点">${heading}<div class="x-sample"><span class="x-badge">${x.count===100?'100 条样本':'部分样本 · '+x.count+' 条'}</span><span>采集：${escapeHTML(X_INSIGHTS.collectedDate)}</span><span>本人帖子日期：${escapeHTML(x.ownPostDateRange.join(' — '))}</span></div><p class="x-context">从 @${escapeHTML(x.handle)} 的主页样本中提炼，以下为编辑转述，原帖可逐条核对。${x.count<100?'仅返回 '+x.count+' 条，未确认最近 100 条的完整覆盖。':''}</p><div class="x-ideas">${x.insights.map((i,n)=>`<article class="x-idea"><span class="idea-number">${String(n+1).padStart(2,'0')}</span><div><h3>${escapeHTML(i.title)}</h3><p>${escapeHTML(i.summary)}</p><div class="x-sources">${i.sources.map((s,n)=>link(s.url,'原帖 '+(n+1)+' · '+s.published.slice(0,10))).join('')}</div></div></article>`).join('')}</div><details class="x-method"><summary>采集范围与阅读边界</summary><p>主页样本包含原创、引用和转推，排除置顶，可能夹带部分推文串回复；不等同于严格按时间截取的最近 100 条原创发言。样本中纯转推 ${x.reposts} 条，带引用的本人帖子 ${x.quotes} 条。提炼时排除纯转推，区分作者、引用者和访谈嘉宾的观点。</p><p>未逐一核验附带图片、视频和外链。推广、个人经验及适用范围在总结中注明。本页为固定采集快照，不自动更新。</p><a href="x-insights.json" download>下载本批观点与来源数据 ↗</a></details></section>`;
}
function renderProfile(){const p=BUILDERS.find(p=>p.id===selected);const [question,action]=LEARNING[p.id];$('#profile').innerHTML=`<div class="profile-topline"><a href="#overview">← 返回理解地图</a><span>${escapeHTML(p.category)} · ${escapeHTML(p.origin)}</span></div><div class="profile-header"><div class="profile-number">FILE ${String(BUILDERS.indexOf(p)+1).padStart(2,'0')} / 30</div><h1 lang="en">${escapeHTML(p.name)}</h1><p class="role">${escapeHTML(p.role)}</p><div class="profile-social">${link(p.home,'网站／作品','')}${link(p.x,'X 账号','')}</div></div><div class="question-block"><span class="eyebrow">START WITH A QUESTION</span><h2>${escapeHTML(question)}</h2><p>${escapeHTML(p.thesis)}</p></div><div class="section-heading"><span class="eyebrow">01 / UNDERSTAND</span><h2>${p.official?'理解官方内容主线':'读懂这些观点'}</h2></div><div id="lesson-formats" class="lesson-formats" aria-label="阅读方式"></div><div id="lesson"></div><section class="exercise"><span class="eyebrow">02 / TRY IT</span><h2>把观点放进一个实际任务</h2><p>${escapeHTML(action)}</p><small>编辑设计的练习，不是作者原话。请用实际结果检验适用范围。</small></section>${recentXHTML(p)}<details class="archive"><summary><span><span class="eyebrow">04 / GO TO THE SOURCE</span><strong>完整档案与 ${p.works.length} 条代表内容</strong></span><span class="disclosure-icon" aria-hidden="true">＋</span></summary><div class="archive-body"><p class="summary">${escapeHTML(p.summary)}</p>${archiveHTML(p)}</div></details>`;renderLesson();document.title=`${p.name} · Builder Atlas`;}
function route(){stopPlayer();const id=location.hash.slice(1);selected=BUILDERS.some(p=>p.id===id)?id:'overview';step=0;format='diagram';if(selected==='overview')renderOverview();else renderProfile();renderIndex();$('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');}
$('#search').addEventListener('input',renderIndex);
$('#categories').addEventListener('click',e=>{const b=e.target.closest('[data-cat]');if(b){category=b.dataset.cat;renderCategories();renderIndex();document.querySelector(`[data-cat="${category}"]`)?.focus({preventScroll:true});}});
$('#menu').addEventListener('click',()=>{const open=$('#sidebar').classList.toggle('open');$('#menu').setAttribute('aria-expanded',String(open));});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){$('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');}});
$('#profile').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.method!==undefined){methodFormat=Number(b.dataset.method);renderMethod();return;}if(b.dataset.format){stopPlayer();format=b.dataset.format;renderLesson();return;}if(b.dataset.step!==undefined){stopPlayer();step=Number(b.dataset.step);renderLesson();return;}if(b.dataset.control){const p=BUILDERS.find(p=>p.id===selected);if(b.dataset.control==='play'){if(timer)stopPlayer();else {if(step===p.ideas.length-1)step=0;timer=setInterval(()=>{step++;if(step>=p.ideas.length-1){step=p.ideas.length-1;stopPlayer();}renderLesson();},8000);}}else {stopPlayer();step=Math.max(0,Math.min(p.ideas.length-1,step+(b.dataset.control==='next'?1:-1)));}renderLesson();}});
$('#profile').addEventListener('change',e=>{if(e.target.matches('#test-check,#human-check')){const checks=Number($('#test-check').checked)+Number($('#human-check').checked);$('#demo-result').textContent=['已生成代码，尚未完成验收。','只完成一项检查，还需核对另一项。','示例中的两项验收已完成，可以考虑交付。'][checks];}});
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(!a)return;$('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');if(a.getAttribute('href')===location.hash&&location.hash!=='#method'){route();window.scrollTo({top:0,behavior:'instant'});}});
window.addEventListener('hashchange',()=>{if(location.hash==='#method')return;route();window.scrollTo({top:0,behavior:'instant'});});
window.addEventListener('pagehide',stopPlayer);
renderCategories();route();
